// Verus solution for left-rotating an array by a non-negative offset.
//
// Spec: for all i in [0, n), b[i] == a[(i + offset) % n], where n = a.len().
// Empty arrays return empty arrays.
//
// Notes on arithmetic safety:
// - We assume a.len() < 1_000_000 and offset < 1_000_000 (as stated).
// - We also assume both are < usize::MAX / 2, so i + offset cannot overflow usize
//   for any i < n (since i < n <= usize::MAX/2 and offset < usize::MAX/2).
// - We reduce offset modulo n when n > 0.

use vstd::prelude::*;

verus! {

fn rotate(a: Vec<int>, offset: usize) -> (b: Vec<int>)
    ensures
        b.len() == a.len(),
        a.len() == 0 ==> b.len() == 0,
        a.len() > 0 ==> (forall|i: int|
            0 <= i < b.len() ==> b[i] == a[((i as usize + (offset % a.len())) % a.len()) as int]
        )
{
    let n = a.len();

    // Empty input => empty output
    if n == 0 {
        return Vec::new();
    }

    let k = offset % n;

    let mut b: Vec<int> = Vec::with_capacity(n);
    let mut i: usize = 0;

    while i < n
        invariant
            n == a.len(),
            n > 0,
            k == offset % n,
            b.len() == i,
            b.len() <= n,
            // Partial correctness: b[0..i) is already the rotated prefix
            forall|j: int|
                0 <= j < i as int ==>
                    b[j] == a[((j as usize + k) % n) as int]
    {
        // Safe by assumptions: i + k doesn't overflow, and modulo keeps index < n.
        let src = (i + k) % n;
        b.push(a[src]);

        i += 1;
    }

    b
}

} // verus!